async function docView(id,docKind='company',historical=false){let list=docKind==='worker'?(D.workerDocsCache[(S.workers[wIndex].passport||S.workers[wIndex].name||'').trim().toUpperCase()]||[]):D.docs;let item=list.find(x=>String(x.id)===String(id));if(!item&&historical){item={id,original_name:historical,title:historical}}if(!item)return toast('Document not found',true);kind=docKind;show('Document preview',`${card(`<h3>${esc(item.title||item.doc_type||item.original_name)}</h3><p>${esc(item.original_name||'')}</p><div id="filePreview" class="file-preview"><div class="empty-state">Loading preview…</div></div><div class="button-row wrap">${btn('Download','doc-download:'+esc(id))}${!historical&&kind==='company'?btn('Version history','doc-history:'+esc(id),'outline'):''}</div>`)}`,true);try{let f=await D.documentBlob(item,docKind);if(!f)throw Error('No file data found in this browser');if(docPreviewUrl)URL.revokeObjectURL(docPreviewUrl);docPreviewUrl=URL.createObjectURL(f);let isPdf=f.type.includes('pdf')||/\.pdf$/i.test(item.original_name||''),isImage=f.type.startsWith('image/')||/\.(jpg|jpeg|png|webp|gif)$/i.test(item.original_name||'');let box=$('#filePreview');if(!box)return;box.innerHTML=isPdf?`<iframe title="Document preview" class="preview-frame" src="${docPreviewUrl}"></iframe>`:isImage?`<img class="preview-image" alt="${esc(item.title||'Document')}" src="${docPreviewUrl}">`:empty('Preview not supported for this file type','Use Download to open it in another app.');box.dataset.filename=item.original_name||'document';}catch(e){if($('#filePreview'))$('#filePreview').innerHTML=empty('Cannot preview document',e.message);toast(e.message,true)}}
async function docHistory(id){let x=D.docs.find(d=>String(d.id)===String(id));if(!x)return;show('Document history',`<p class="subtext">${esc(x.title)}</p><div id="historyList">Loading versions…</div>`);try{let hist=await D.historyDoc(x);if(!$('#historyList'))return;$('#historyList').innerHTML=hist.map(x=>`<div class="file-row"><div class="file-icon">v${esc(x.version)}</div><div class="grow"><b>${esc(x.original_name||'File')}</b><small>${esc(x.uploaded_at||'')}</small></div>${btn('View','doc-history-view:'+esc(x.id),'outline small')}</div>`).join('')||empty('No history entries')}catch(e){toast(e.message,true)}}
